parameters.functionCode:
const customers = $input.all().map(i => i.json);
if (!customers.length || !customers[0].id) return [];

return customers.map(customer => ({
  json: {
    deal_id: customer.id,
    contact_id: customer.contact_id,
    email: customer.email,
    first_name: customer.first_name,
    last_name: customer.last_name,
    company: customer.company,
    deal_value: customer.deal_value,
    assigned_to: customer.assigned_to,
    client_id: customer.client_id,
    onboarding_steps: [
      { step: 1, name: 'welcome_email', delay_hours: 0, status: 'pending' },
      { step: 2, name: 'account_setup_guide', delay_hours: 24, status: 'pending' },
      { step: 3, name: 'kickoff_meeting_invite', delay_hours: 48, status: 'pending' },
      { step: 4, name: 'training_resources', delay_hours: 72, status: 'pending' },
      { step: 5, name: 'check_in_call', delay_hours: 168, status: 'pending' },
      { step: 6, name: 'feedback_survey', delay_hours: 336, status: 'pending' }
    ]
  }
}));

